+            return 0;
+        }
+        final int bytesRead;
+        if (luceneByteBufLock.readLock().tryLock()) {
+            try {
+                boolean shouldStopReading = stopAsyncReads.get();
+                if (shouldStopReading) {
+                    // return fake response
+                    return Math.toIntExact(length);
