+            throw new EOFException("Reading past end of file [position=" + pos + ", length=" + length() + "] for " + toString());
+        } else if (pos < 0L) {
+            throw new IOException("Seeking to negative position [" + pos + "] for " + toString());
+        }
+        final long position = pos + this.offset;
+        stats.incrementSeeks(lastSeekPosition, position);
+        lastSeekPosition = position;
+    }
+
+    @Override
+    public FrozenIndexInput clone() {
+        return (FrozenIndexInput) super.clone();
+    }
+
+    @Override
+    public IndexInput slice(String sliceDescription, long offset, long length) {
+        if (offset < 0 || length < 0 || offset + length > length()) {
+            throw new IllegalArgumentException(
+                "slice() "
+                    + sliceDescription
+                    + " out of bounds: offset="
+                    + offset
+                    + ",length="
+                    + length
+                    + ",fileLength="
+                    + length()
+                    + ": "
+                    + this
+            );
+        }
+        final FrozenIndexInput slice = new FrozenIndexInput(
+            getFullSliceDescription(sliceDescription),
+            directory,
+            fileInfo,
+            context,
+            stats,
+            this.offset + offset,
+            length,
+            frozenCacheFile,
+            defaultRangeSize,
+            recoveryRangeSize
+        );
+        slice.isClone = true;
+        return slice;
+    }
+
+    @Override
+    public String toString() {
+        return "CachedBlobContainerIndexInput{"
+            + "sharedCacheFile="
+            + frozenCacheFile
+            + ", offset="
+            + offset
+            + ", length="
+            + length()
+            + ", position="
+            + getFilePointer()
+            + ", rangeSize="
+            + getDefaultRangeSize()
+            + ", directory="
+            + directory
